import os
os.environ.setdefault('OPENBLAS_NUM_THREADS','1')
import numpy as np, mujoco, rcb_dtb
from scipy.spatial.transform import Rotation as Rot
from PIL import Image
class Controller:
 def __init__(self,s):
  self.s=s; self.m=s.model;self.d=s.data;self.k=mujoco.MjData(self.m); self.bid=self.m.body('palmleft_hand_C_MC').id
 def pose(self):return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,p,R,q=None,n=80):
  if q is None:q=self.s.targets.copy()
  q=q.copy(); self.k.qpos[:]=self.d.qpos
  jp=np.zeros((3,self.m.nv));jr=jp.copy()
  for it in range(n):
   self.k.qpos[self.s._jq]=q;mujoco.mj_forward(self.m,self.k)
   err=np.r_[p-self.k.xpos[self.bid],Rot.from_matrix(R@self.k.xmat[self.bid].reshape(3,3).T).as_rotvec()]
   if np.linalg.norm(err)<1e-5:break
   mujoco.mj_jacBody(self.m,self.k,jp,jr,self.bid);J=np.vstack([jp[:,:7],jr[:,:7]])
   delta=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,err)
   delta*=min(1,.12/(np.max(np.abs(delta))+1e-9));q[:7]=np.clip(q[:7]+delta,self.s.lower[:7]+.001,self.s.upper[:7]-.001)
  return q
 def move(self,p,R,hand=None,steps=120):
  p0,R0=self.pose();rv=Rot.from_matrix(R@R0.T).as_rotvec();h0=self.s.targets[7:].copy()
  for t in range(steps):
   f=(t+1)/steps;f=f*f*(3-2*f)
   q=self.ik(p0+(p-p0)*f,Rot.from_rotvec(rv*f).as_matrix()@R0,n=15)
   if hand is not None:q[7:]=h0+(hand-h0)*f
   self.s.step(q)
 def hold(self,n=60):
  for _ in range(n):self.s.step(self.s.targets)
 def snap(self,name):
  Image.fromarray(self.s.render_grid(size=(640,480))).save('/app/output/'+name+'.png')
 def contacts(self):
  out={}
  for c in self.d.contact:
   a,b=c.geom1,c.geom2
   if self.m.geom_bodyid[a]==self.s._obj or self.m.geom_bodyid[b]==self.s._obj:
    f=np.zeros(6);mujoco.mj_contactForce(self.m,self.d,list(self.d.contact).index(c) if False else 0,f)
    key=(self.m.geom(a).name,self.m.geom(b).name);out[key]=min(c.dist,out.get(key,1))
  print(out,flush=True)
def hand(curl=1.2,thumb=[1.2,0,.5,0,.8]):
 h=np.zeros(22);h[:5]=thumb
 for j in [5,9,13,18]:h[j:j+4]=[curl,0,1.5,1.1]
 return h

def grasp(s,c,dx=.045,dz=.11,dy=0,close=1.3,thumb=[1.2,0,.5,0,.8],snaps=False):
 for _ in range(20):s.step(s.targets)
 O=s.data.xpos[s._obj].copy(); Ro=s.data.xmat[s._obj].reshape(3,3).copy()
 y=-Ro[:,0];y[2]=0;y/=np.linalg.norm(y);x=np.array([0,0,-1.]);z=np.cross(x,y);R=np.stack([x,y,z],axis=1)
 p=O-R@np.array([dx,dy,dz])
 c.move(p+[0,0,.11],R,steps=150)
 if snaps:c.snap('approach')
 c.move(p,R,steps=180)
 if snaps:c.snap('pregrasp')
 c.move(p,R,hand(close,thumb),steps=180);c.hold(60)
 if snaps:c.snap('closed');c.contacts()
 print('grasp',s.state()['object_pos'],s.state()['q'][7:],flush=True)
 c.move(p+[0,0,.13],R,steps=180);c.hold(60)
 if snaps:c.snap('lifted');c.contacts()
 print('lift',s.state()['object_pos'],s.progress(),flush=True)
 return R
if __name__=='__main__':
 s=rcb_dtb.Session();c=Controller(s);s.record_start();grasp(s,c,snaps=True);A=s.record_stop();s.save_trajectory(A,'/app/output/test.npz')
